-- Shimmering Expanse: creature abilities
-- Most of the zone's creatures (the naga, the Zin'jatar, the Twilight's Hammer, the elementals and the sea creatures) had no AI or
-- ran classic rows: port their abilities from the Cataclysm data, falling back to the classic data where Cataclysm has none,
-- keeping the quest scripts already in place; gossip and quest reward scripts of the references are left out. The creatures no
-- reference scripts cast their sniffed spells (creature_template spell1-8).

SET @ENTRIES := '39389,39397,39418,39419,39602,39638,39664,39796,40162,40200,40237,40238,40239,40275,40280,40372,40710,40728,40798,40831,40878,40889,40911,40912,41102,41105,41106,41107,41108,41227,41228,41249,41250,41256,41326,41451,41466,41467,41517,41520,41526,41527,41537,41566,41569,41573,41579,41606,41607,41608,41609,41731,41780,41784,41795,41896,41994,41995,42058,42060,42061,42062,42063,42069,42181,42341,42453,46468,47397';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);

-- Creatures without reference data: their sniffed creature_template spell1-8
SET @ENTRIES := '39411,40510,41115,41518,41521,41874,42418,42726,46470,50571,50572,50573';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
